source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    stripe_rows = []
    for r, row in enumerate(g):
        nz = [c for c, v in enumerate(row) if v]
        if len(nz) >= 3 and any(row[c] == 0 for c in range(nz[0], nz[-1] + 1)):
            stripe_rows.append(r)
            # Fill each internal zero run from its nearest colored side.
            for c in range(nz[0], nz[-1] + 1):
                if row[c] == 0:
                    left = next((row[j] for j in range(c - 1, -1, -1) if row[j]), None)
                    right = next((row[j] for j in range(c + 1, w) if row[j]), None)
                    if left is not None and right is not None:
                        row[c] = left if left == right or c - nz[0] <= nz[-1] - c else right
    if not stripe_rows:
        return g
    last = max(stripe_rows)
    # Bottom vertical markers identify the columns whose gaps continue upward.
    marker_cols = {}
    for c in range(w):
        vals = [(r, g[r][c]) for r in range(last + 1, h) if g[r][c]]
        if vals:
            marker_cols[c] = vals[-1][1]
    for c, marker_color in marker_cols.items():
        events = []
        for r in stripe_rows:
            if grid[r][c] == 0 and g[r][c] != 0:
                # The filled cell must have colored neighbors on both sides.
                if any(grid[r][j] for j in range(c)) and any(grid[r][j] for j in range(c + 1, w)):
                    events.append((r, g[r][c]))
        if not events:
            continue
        for i, (r, color) in enumerate(events):
            start = 0 if i == 0 else events[i - 1][0] + 1
            for rr in range(start, r + 1):
                g[rr][c] = color
        for rr in range(events[-1][0] + 1, h):
            g[rr][c] = marker_color
    return g
